(1890, 3, 58, 109, 'Red Roach Pack Of 100 gS2 G2 - GS1312', 'red-roach-pack-of-100-gs2-g2-gs1312', '6921690984231', 0.00, 0.00, 0.00, 0, 'per_quantity', 'Red Roach Pack of 100 includes ready-to-use rolling roach tips, designed to create a firm, smooth, and comfortable mouthpiece for hand-rolled products.', '<p data-end=\"470\" data-start=\"230\"><strong data-end=\"248\" data-start=\"230\">Red Roach Tips</strong> are a practical smoking accessory, perfect for customers who prefer a neat and easy rolling experience. Each roach is simple to shape and helps provide better structure, airflow, and comfort when used with rolling papers.</p>\r\n\r\n<p data-end=\"617\" data-start=\"472\">This <strong data-end=\"492\" data-start=\"477\">pack of 100</strong> is ideal for retail counters, smoke shops, convenience stores, cash &amp; carry outlets, and wholesale smoking accessory ranges.</p>\r\n\r\n<h3 data-end=\"637\" data-section-id=\"1sboupi\" data-start=\"619\">Key Features</h3>\r\n\r\n<ul data-end=\"871\" data-is-last-node=\"\" data-is-only-node=\"\" data-start=\"638\">\r\n	<li data-end=\"668\" data-section-id=\"py2k6r\" data-start=\"638\">Pack of 100 red roach tips</li>\r\n	<li data-end=\"695\" data-section-id=\"1v5ceqs\" data-start=\"669\">Easy to roll and shape</li>\r\n	<li data-end=\"730\" data-section-id=\"1bohzam\" data-start=\"696\">Helps create a firm mouthpiece</li>\r\n	<li data-end=\"763\" data-section-id=\"1tb8ex8\" data-start=\"731\">Improves airflow and comfort</li>\r\n	<li data-end=\"790\" data-section-id=\"15wyuwd\" data-start=\"764\">Compact and convenient.</li>\r\n</ul>\r\n', 'tqmenamxet112uxc11fn3gmj_large1781963951.png', NULL, NULL, NULL, NULL, 0, 0, 1, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 0, '2026-06-20 16:31:51', '2026-06-20 19:29:11'),
(1891, 3, 58, 109, 'GS1178 - HONEYPUFF PK50 TIPS ORGANIC BROWN P8169', 'gs1178-honeypuff-pk50-tips-organic-brown-p8169', '10860004735059', 0.00, 0.00, 0.00, 0, 'per_quantity', 'HoneyPuff Organic Brown Filter Tips PK50 are natural, unbleached rolling tips designed for a cleaner and smoother rolling experience. Compact, easy to use, and ideal for everyday smokers.', '<p data-end=\"527\" data-start=\"293\"><strong data-end=\"332\" data-start=\"293\">HoneyPuff Organic Brown Filter Tips</strong> are made for customers who prefer a more natural rolling accessory. These brown, unbleached filter tips are easy to roll, firm to use, and help create a neat mouthpiece for hand-rolled products.</p>\r\n\r\n<p data-end=\"808\" data-start=\"529\">Each pack contains <strong data-end=\"567\" data-start=\"548\">50 tip booklets</strong>, making it a great wholesale option for convenience stores, smoke shops, cash &amp; carry retailers, and smoking accessory suppliers. The organic brown finish gives the tips a natural look while keeping them practical, clean, and easy to carry.</p>\r\n\r\n<h3 data-end=\"828\" data-section-id=\"1sboupi\" data-start=\"810\">Key Features</h3>\r\n\r\n<ul data-end=\"1117\" data-is-last-node=\"\" data-is-only-node=\"\" data-start=\"829\">\r\n	<li data-end=\"868\" data-section-id=\"1mtc13z\" data-start=\"829\">HoneyPuff organic brown filter tips</li>\r\n	<li data-end=\"892\" data-section-id=\"dwxdoa\" data-start=\"869\">Pack of 50 booklets</li>\r\n	<li data-end=\"928\" data-section-id=\"sd8ldj\" data-start=\"893\">Natural unbleached brown finish</li>\r\n	<li data-end=\"955\" data-section-id=\"1v5ceqs\" data-start=\"929\">Easy to roll and shape</li>\r\n	<li data-end=\"993\" data-section-id=\"u7bja5\" data-start=\"956\">Helps improve airflow and comfort</li>\r\n	<li data-end=\"1020\" data-section-id=\"pqtovs\" data-start=\"994\">Compact booklet format.</li>\r\n</ul>\r\n', 'okrorn33sohq5klmu4vt5kyl_large1781963625.png', NULL, NULL, NULL, NULL, 0, 0, 1, '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 0, '2026-06-20 16:31:51', '2026-06-20 19:23:45'),
